:root {
  --menu-item-margin: 0 4px;
  --menu-item-padding: 4px;

  /* UI Density customization */

  &[uidensity="compact"] {
    --menu-item-margin: 0 3px;
    --menu-item-padding: 3px;

    & menupopup {
      --panel-padding: 3px 0;
    }
  }

  &[uidensity="touch"] {
    --menu-item-padding: 9px;
  }
}

menupopup {
  /* Complement the :is(menu, menuitem) margin. */
  --panel-padding: 4px 0;
  --menuitem-icon-fill: color-mix(in srgb, currentColor 20%, transparent);
  font: menu;
  font-size: inherit;
  text-align: start;
  min-inline-size: 12ch;

  @media (-moz-windows-mica-popups) {
    --panel-background-color: Menu !important;
    --panel-border-color: transparent !important;
  }

  :root:not([lwtheme]) menubar > menu & {
    --panel-background-color: Menu;
    --panel-text-color: MenuText;
  }

  & > :is(menu, menuitem) {
    appearance: none;
    margin: var(--menu-item-margin);
    min-block-size: 24px;
    padding-inline: 8px;
    padding-block: var(--menu-item-padding);
    border-radius: 3px;
    background-color: transparent;

    &:focus {
      outline: 0;
    }

    &[checked],
    &[selected] {
      --menuitem-icon: var(--icon-check);
      -moz-context-properties: fill, stroke;
      stroke: currentColor;
      color: inherit;
    }

    &:not([disabled], :active)[_moz-menuactive] {
      color: inherit;
      background-color: var(--panel-background-color-dimmed);
    }

    &:not([disabled])[_moz-menuactive]:active {
      color: inherit;
      background-color: var(--panel-background-color-dimmed-further);
      box-shadow: 0 1px 0 hsla(210, 4%, 10%, 0.03) inset;
    }

    &[disabled],
    &[disabled]:hover,
    &[checked][disabled],
    &[checked][disabled]:hover {
      color: var(--text-color-disabled);
      background-color: transparent;
    }

    & > .menu-text {
      appearance: none;
      margin-inline-start: 0;
    }
  }

  :root:not([lwtheme]) menubar > menu & > :is(menu, menuitem):not([disabled])[_moz-menuactive] {
    color: inherit;
    background-color: var(--panel-background-color-dimmed-further);
  }

  & > menu::after {
    -moz-context-properties: stroke, fill-opacity;
    content: var(--icon-nav-right-sm);
    stroke: currentColor;
    background-image: none;
    margin-inline-start: 10px;
  }

  & > menu:-moz-locale-dir(rtl)::after {
    content: var(--icon-nav-left-sm);
  }

  & > menuseparator {
    padding-inline: 8px;
  }

  &.no-accel-menupopup > :is(menu, menuitem) > .menu-accel {
    display: none;
  }

  /* NOTE: the menuitem children must be constructed with the menuitem-iconic
   * class so that this rule can hide the icon container. */
  &.no-icon-menupopup > :is(menu, menuitem) > .menu-icon {
    display: none;
  }

  /* Always show the extension icons. */
  &.no-icon-menupopup > :is(menu, menuitem).webextension-rootElement > .menu-icon {
    display: flex;
  }
}

